// Accept a raw webhook POST (data under .body) or a direct/sub-workflow call.
const raw = $input.first().json;
const src = raw.body || raw.lead || raw;

const clean = (v) => (v === undefined || v === null || v === false || v === '') ? null : String(v).trim();

const email = clean(src.email);
const phone = clean(src.phone) || clean(src.whatsapp);

if (!email && !phone) {
  throw new Error('Rejected: inbound lead has neither an email nor a phone number. Keys received: ' + Object.keys(src).join(', '));
}

// ---- TENANT (18 Sep 2026) -------------------------------------------------
// REPLACES the 2 Sep resolver, which read `src.tenant_id` FIRST and only fell
// back to the JWT. That order let an authenticated user of dealership A post
// `tenant_id: <B>` and have this workflow create the leads row under B --
// n8n writes as service_role, which is BYPASSRLS, so nothing downstream would
// have stopped it. The caller's tenant_id is now never a source. It is only
// ever a claim, and a claim that disagrees with the membership row is refused.
//
// Two doors, two rules:
//   * public webhook  -- `Webhook Catch-All` -> `Verify JWT` ->
//     `Tenant For JWT User` -> `Auth Gate` -> here. The ONLY trusted answer is
//     the tenant_members row for the Supabase user behind the verified JWT.
//     No row, or more than one row, means refuse; there is no fallback on this
//     door, because a fallback is exactly how an unverifiable caller acquires
//     a dealership.
//   * internal hop    -- `Called Internally` -> here. The caller is a sibling
//     workflow that already resolved the dealership; `Auth Gate` never ran, so
//     that is how this node tells the doors apart.
//
// Refusals carry the '[NEXUS-UNATTRIBUTED]' prefix at position 0, the contract
// with the NEXUS Error Handler (iYJkh1kztWxZXDbT): the failed execution is
// filed under the quarantine tenant instead of being appended to some real
// dealership's audit trail.
const NEXUS_BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // Tenant A
const NEXUS_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let nexusMap = {};
try { nexusMap = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { nexusMap = {}; }
if (!nexusMap || typeof nexusMap !== 'object' || !Object.keys(nexusMap).length) nexusMap = NEXUS_BUILTIN;
const nexusKeys = Object.keys(nexusMap);

// What the caller ASSERTED. Never authoritative; only ever cross-checked.
const claimed = String(src.tenant_id || raw.tenant_id || '');

// Which door? `$()` throws for a node that did not run in this execution.
let viaWebhook = true;
try { $('Auth Gate').all(); } catch (e) { viaWebhook = false; }

let tenant = null;
let tenantSource = 'unresolved';

if (viaWebhook) {
  const ids = Array.from(new Set(
    $('Tenant For JWT User').all()
      .map((i) => (i && i.json ? i.json.tenant_id : null))
      .filter(Boolean)
      .map(String)
  ));
  if (ids.length > 1) {
    throw new Error('[NEXUS-UNATTRIBUTED] Lead rejected: the authenticated user is a member of ' + ids.length + ' dealerships. This endpoint will not choose one on their behalf.');
  }
  if (ids.length === 0 || !NEXUS_UUID.test(ids[0])) {
    throw new Error('[NEXUS-UNATTRIBUTED] Lead rejected: the authenticated user has no tenant_members row. A dealership is never taken from the request body.');
  }
  if (claimed && claimed.toLowerCase() !== ids[0].toLowerCase()) {
    throw new Error('[NEXUS-UNATTRIBUTED] Lead rejected: caller asserted tenant_id ' + claimed + ' but is a member of ' + ids[0] + '. tenant_id is not a caller-selectable field.');
  }
  tenant = ids[0];
  tenantSource = 'jwt_tenant_member';
} else {
  if (NEXUS_UUID.test(claimed)) {
    tenant = claimed;
    tenantSource = 'internal_caller';
  } else if (nexusKeys.length === 1 && NEXUS_UUID.test(String(nexusMap[nexusKeys[0]] || ''))) {
    tenant = String(nexusMap[nexusKeys[0]]);
    tenantSource = 'sole_configured_tenant';
  } else {
    throw new Error('[NEXUS-UNATTRIBUTED] Lead rejected: the internal caller supplied no resolvable tenant_id and ' + nexusKeys.length + ' dealerships are configured. Refusing rather than filing this lead under a guess.');
  }
}

return [{
  json: {
    lead: {
      name: clean(src.name) || clean(src.full_name) || 'Unknown',
      email: email,
      phone: phone,
      vehicle_interest: clean(src.vehicle_interest) || clean(src.vehicleInterest) || clean(src.message) || null,
      budget_aed: src.budget_aed ? Number(src.budget_aed) : null,
      source: clean(src.source) || 'webhook',
      // Travels with the lead so the sub-workflows this router fans out to --
      // the BDC agent, the drip, the ERP sync -- write under the right
      // dealership too.
      tenant_id: tenant,
      tenant_source: tenantSource,
      // Who handed us this lead. 'whatsapp-bdc' means the person is ALREADY in
      // a live WhatsApp thread that the BDC agent has just answered, so the
      // outreach branches below must not fire a canned welcome at them on top
      // of the reply they are reading right now. Everything else -- scoring,
      // the Slack alert, the ERP write, the drip -- still applies.
      origin: clean(src.origin) || 'external',
      received_at: new Date().toISOString()
    }
  }
}];

// SCORING AUTHORITY — read this before changing a number.
//
// 14 Sep 2026 (ADR-003). Zero paying dealers, so the model ladder is entirely
// free-tier and none of those models support structured output. A free model
// that collapses into babble produced ai_score 0 on 13 Sep, and an empty `{}`
// response produced a confident-looking WARM/50. Neither was a verdict.
//
// So: DETERMINISTIC RULES DECIDE. The model still runs, its answer is still
// recorded, and it is labelled as a non-authoritative signal. When two paying
// dealers justify a paid model with real structured output, flip the one
// constant below to 'AI' and the labels flip with it. No schema change.
const AUTHORITY = 'RULES';   // 'RULES' today | 'AI' once a paid structured model is in

const lead = $('Validate & Enrich Input').first().json.lead;
const rawOut = $input.first().json;

// Rules-engine short-circuit: when every AI tier is exhausted, the
// "Rule-Based Lead Scorer" node hands us an already-finished decision
// instead of raw agent text. Detect it by score_source and pass it straight
// through -- do NOT try to regex/JSON-parse it as if it were LLM output.
if (rawOut.ai_decision && rawOut.ai_decision.score_source === 'RULES') {
  return [{ json: { lead: rawOut.lead || lead, ai_decision: rawOut.ai_decision } }];
}

const text = String(rawOut.output ?? rawOut.text ?? '').trim();

// ---------------------------------------------------------------- the model
function extractJson(s) {
  if (!s) return null;
  try { return JSON.parse(s); } catch (e) {}
  const fenced = s.replace(/```(?:json)?/gi, '').trim();
  try { return JSON.parse(fenced); } catch (e) {}
  const first = fenced.indexOf('{');
  const last = fenced.lastIndexOf('}');
  if (first !== -1 && last > first) {
    try { return JSON.parse(fenced.slice(first, last + 1)); } catch (e) {}
  }
  return null;
}

const parsed = extractJson(text);

// A parse that "succeeds" on `{}` is not a verdict. Both fields must actually
// be present and valid, or this is a fallback. That closes the hole where an
// empty model response was indistinguishable from a genuine WARM/50.
const aiIntentRaw = parsed && typeof parsed === 'object'
  ? String(parsed.intent || '').toUpperCase() : '';
const aiScoreNum = parsed && typeof parsed === 'object' ? Number(parsed.score) : NaN;
const aiStructured =
  ['HOT', 'WARM', 'COLD'].includes(aiIntentRaw) && Number.isFinite(aiScoreNum);

const ai = {
  intent: aiStructured ? aiIntentRaw : null,
  score:  aiStructured ? Math.max(0, Math.min(100, Math.round(aiScoreNum))) : null,
  reason: (parsed && parsed.reason) ? String(parsed.reason) : null,
  structured: aiStructured
};

// Budget: only ever trusted from structured JSON. The prose fallback cannot
// tell a budget from a price, a year or a phone number, and a wrong budget is
// worse than none.
const rawBudget = aiStructured ? Number(parsed.budget_aed) : NaN;
const aiBudget = Number.isFinite(rawBudget) && rawBudget > 0 ? Math.round(rawBudget) : null;

// ---------------------------------------------------------------- the rules
// Explainable, deterministic, and every point is attributable to a named
// signal. Nothing here can hallucinate and nothing here can time out.
const msg = String(lead.vehicle_interest || '').toLowerCase();
const budget = Number(lead.budget_aed) > 0 ? Number(lead.budget_aed) : (aiBudget || 0);

const BUY   = /\b(price|pricing|quote|cost|how much|buy|buying|purchase|test drive|testdrive|book|booking|reserve|available|availability|finance|financing|emi|installment|instalment|down payment|cash|trade[- ]?in|exchange)\b/;
const URGENT= /\b(today|tonight|now|asap|urgent|urgently|immediately|tomorrow|this week|right away)\b/;
const GREET = /^(hi|hello|hey|salam|assalam|as-salamu|good (morning|afternoon|evening)|thanks|thank you|ok|okay)\W*$/;

let score = 20;
const why = [];
const add = (n, label) => { score += n; why.push((n >= 0 ? '+' : '') + n + ' ' + label); };

if (lead.phone) add(25, 'reachable by phone');
if (lead.email) add(10, 'email present');

if (!msg)                 add(-15, 'no enquiry text');
else if (GREET.test(msg)) add(-10, 'greeting only, no enquiry');
else if (msg.length >= 3) add(20, 'named an enquiry');

if (BUY.test(msg))    add(25, 'buying-intent phrase');
if (URGENT.test(msg)) add(15, 'urgency phrase');

if (budget >= 100000)   add(15, 'budget >= AED 100k');
else if (budget > 0)    add(10, 'budget stated');

if (String(lead.origin || '') === 'whatsapp-bdc') add(10, 'already in a live WhatsApp thread');

score = Math.max(0, Math.min(100, score));

// No enquiry text and no budget is not a cold lead, it is an unreadable one.
// Send it to a human rather than inventing a temperature for it.
const unreadable = !msg && budget <= 0;
const rules = {
  intent: unreadable ? 'UNKNOWN' : (score >= 70 ? 'HOT' : (score >= 40 ? 'WARM' : 'COLD')),
  score: score,
  reason: unreadable
    ? 'No enquiry text and no budget — rules cannot classify this lead. Needs a human.'
    : ('Rules: ' + why.join(', ') + ' = ' + score + '.')
};

// ------------------------------------------------------------ who decides
const useAi = AUTHORITY === 'AI' && ai.structured;
const decided = useAi ? ai : rules;

// One label, three values, never mixed in a metric.
//   RULES              — the deterministic scorer decided (today's default)
//   AI_SCORE_CONFIRMED — the model returned valid structured JSON and decided
//   AI_SCORE_FALLBACK  — the model did not return a usable verdict
const score_source = useAi
  ? 'AI_SCORE_CONFIRMED'
  : (AUTHORITY === 'AI' ? 'AI_SCORE_FALLBACK' : 'RULES');

const ai_decision = {
  intent: decided.intent,
  score: decided.score,
  reason: [decided.reason, ai.reason ? ('Model said: ' + ai.reason) : null]
            .filter(Boolean).join(' | ') || null,
  budget_aed: aiBudget,

  // provenance — persisted, not just logged
  score_source: score_source,
  rules_score: rules.score,
  rules_intent: rules.intent,
  ai_score_raw: ai.score,
  ai_intent_raw: ai.intent,
  ai_structured: ai.structured,

  // kept for the Slack card and the audit row. True whenever the model failed
  // to produce a usable verdict, whether or not the rules covered for it.
  parse_failed: !ai.structured,
  ai_raw_excerpt: ai.structured ? null : text.substring(0, 300)
};

return [{ json: { lead, ai_decision } }];

// n8n's Agent node accepts a maximum of 2 language models, so a deeper
// fallback chain is built as a retry ladder. Each tier swaps the OpenRouter slot.
// 16 Aug 2026: every id below was verified live against OpenRouter -- it exists,
// it is :free (no paid model, per the free-tier rule), and it actually returned
// a tool_call in a real request. The previous ladder had a PAID gemini tier plus
// two dead ids (gemma-4-31b-it:free rate-limited 429, ling-3.0-flash:free is
// 404 free-tier-discontinued), which is why all 4 tiers failed on live traffic.
//
// 29 Aug 2026: REMOVED tier 1, 'nvidia/nemotron-3-ultra-550b-a55b:free'. It failed
// on BOTH agents inside the same real run -- exec 6251 (BDC, 46.5s wasted) and
// exec 6253 (Router, 45.8s wasted) -- with 'Cannot read properties of undefined
// (reading \'message\')'. The ladder escalated correctly each time, so this is not
// a ladder bug: the model is dead and every single request was paying ~45s for it
// before getting a real answer. That latency is also a direct contributor to
// concurrency exhaustion at 5 production slots.
//
// 30 Aug 2026: groqModel changed from 'llama-3.3-70b-versatile' to
// 'openai/gpt-oss-120b' on every tier. Groq SHUT DOWN llama-3.3-70b-versatile
// for free and developer tiers on 16 Aug 2026 -- their deprecations page names
// openai/gpt-oss-120b as the replacement, their models page marks the old id
// Enterprise/Contact-Sales, and it has no row at all in the free-tier
// rate-limit table. Groq is only the FALLBACK slot, so it had never fired in
// production and nothing surfaced this: it would have failed for the first
// time on the day OpenRouter was already down. The same fix went into the
// WhatsApp BDC agent earlier today; this workflow was missed, which meant the
// two agents disagreed about which model exists.
// Free-tier ceiling: 30 RPM / 1K RPD / 8K TPM / 200K TPD -- tokens-per-minute
// binds well before requests-per-minute on an agent this prompt-heavy.
const GROQ_FALLBACK = 'openai/gpt-oss-120b';
const TIERS = [
  { orModel: 'nvidia/nemotron-3.5-lightning:free',       groqModel: GROQ_FALLBACK },
  { orModel: 'nvidia/nemotron-3-super-120b-a12b:free',   groqModel: GROQ_FALLBACK },
  { orModel: 'minimax/minimax-m2.7:free',                groqModel: GROQ_FALLBACK }
];

const prev = $input.first().json;
// NX1002 persist-first bug fix (20 Sep 2026, found live on exec 16124):
// 'Persist Lead (deterministic)' now runs BEFORE this node and uses
// 'Prefer: return=minimal', so its HTTP response body -- and therefore
// $input.first().json on THIS node's first invocation -- is {} with no
// .lead at all. prev.lead was silently undefined on every tier, which fed
// 'undefined' lead data into the AI agent and into 'Rule-Based Lead Scorer',
// and then made 'Update Lead Scoring (PATCH)' fail outright (tenant_id=
// eq.undefined is not a valid uuid), leaving every lead stuck at
// scoring_state='PENDING' forever. Read lead from the named node instead --
// same pattern 'Parse AI Decision' already uses for the same reason -- so it
// is available on every iteration of this retry loop, not just derived from
// this node's own previous (lead-less) output.
const lead = $('Validate & Enrich Input').first().json.lead;
const attempt = Number(prev.attempt ?? -1) + 1;

if (attempt >= TIERS.length) {
  throw new Error('All ' + TIERS.length + ' model tiers failed for lead ' +
    ((lead && lead.email) || 'unknown') + '. Tried: ' +
    TIERS.map(t => t.orModel + ' / ' + t.groqModel).join(', '));
}

return [{ json: {
  lead: lead,
  attempt: attempt,
  maxTiers: TIERS.length,
  orModel: TIERS[attempt].orModel,
  groqModel: TIERS[attempt].groqModel
} }];

