// This node sits ONLY on the public webhook branch.
//
// Until now `POST /webhook/nexus-inbound-lead` was wide open. Anyone who found
// the URL could invent a lead, have an LLM score it, get a row written into
// `leads`, and -- on a HOT verdict -- make the dealership send a WhatsApp
// message to any number they chose. Every other public webhook in this system
// already checks the caller's Supabase session token; this one never did,
// because its only intended caller was Make.com, which no longer exists.
//
// `Called Internally` (the Execute Workflow trigger) connects straight to
// `Validate & Enrich Input` and never reaches here, so n8n-to-n8n calls are
// untouched -- they are already inside the trust boundary.
//
// `Verify JWT` runs with onError = continueRegularOutput, so a rejected token
// arrives as data rather than as a failed HTTP node. Supabase GET
// /auth/v1/user returns the user object on success; no .id means rejected.
//
// 2 Sep 2026: `Tenant For JWT User` was inserted between Verify JWT and this
// node to look the caller's dealership up in tenant_members. That HTTP node
// REPLACES the item, so the identity check now reaches back to Verify JWT by
// name. The guard itself is unchanged: no .id on the verified user, no entry.
let auth = {};
try { auth = $('Verify JWT').first().json || {}; } catch (e) { auth = {}; }
if (!auth.id) {
  // The '[NEXUS-UNATTRIBUTED]' prefix below is a contract with the NEXUS Error
  // Handler (iYJkh1kztWxZXDbT). An execution that failed BEFORE it authenticated
  // its caller belongs to no dealership, so that workflow omits tenant_id and
  // audit_log's own DEFAULT nexus_default_tenant_id() retains the row under the
  // quarantine tenant -- visible to nexus_quarantine_census(), unreadable by any
  // dealership -- instead of appending an anonymous stranger's row to Tenant A'
  // audit trail. Keep the marker at the START of the message: the handler tests
  // position 0, so a copy embedded in a request payload cannot trigger it.
  throw new Error('[NEXUS-UNATTRIBUTED] Inbound lead rejected: unauthorized. A valid Supabase session token is required in the Authorization header.');
}

// Re-emit the ORIGINAL request untouched so `Validate & Enrich Input` sees
// exactly the shape it saw before this guard was inserted.
return $('Webhook Catch-All').all();

// Delivery Report - verify every claim the audit row is about to make.
//
// Only ONE intent branch runs per lead, and `$('Node')` THROWS for a node that
// did not run -- `?.` cannot rescue it -- so the claim list is built from the
// intent that actually fired, and every lookup is still wrapped.
const decision = $('Parse AI Decision').first().json;
const intent = String((decision.ai_decision || {}).intent || 'UNKNOWN').toUpperCase();
const origin = String(((decision.lead) || {}).origin || 'external');

const CLAIMED = [];

// 29 Aug 2026: the lead write is claimed on EVERY branch, unconditionally, and
// it is pushed FIRST so CLAIMED can never be empty.
// Before this, a WARM lead with origin 'whatsapp-bdc' pushed nothing at all --
// the WARM arm has no else -- so results.length was 0 and the report said
// 'all 0 claimed steps verified' with status SUCCESS. Execution 6253 did exactly
// that on a run which created no leads row whatsoever. The report only ever
// verified dispatch; it never verified persistence, which is the one thing every
// downstream journey depends on.
CLAIMED.push({ node: 'Persist Lead (deterministic)', what: 'lead row written to the leads table', critical: true });

if (intent === 'HOT') {
  CLAIMED.push({ node: 'Slack Router (HOT)', what: 'lead escalated to a closer (Slack + email)', critical: true });
  CLAIMED.push({ node: 'ERP Sync (HOT)',     what: 'lead written into the Bitrix24 CRM',        critical: true });
  if (origin !== 'whatsapp-bdc') {
    CLAIMED.push({ node: 'WhatsApp Outreach (HOT)', what: 'WhatsApp outreach to the customer', critical: true });
  }
} else if (intent === 'WARM') {
  if (origin !== 'whatsapp-bdc') {
    CLAIMED.push({ node: 'WhatsApp BDC (WARM)', what: 'WhatsApp outreach to the customer', critical: true });
  }
} else if (intent === 'COLD') {
  // Started, not finished: the drip spans seven days and this node is called
  // with waitForSubWorkflow = false, so the only honest claim is that it began.
  CLAIMED.push({ node: 'Marketing Drip (COLD)', what: 'lead handed to the 7-day drip (start only)', critical: true });
} else {
  CLAIMED.push({ node: 'Slack: Unclassified Lead', what: 'unclassified lead posted to Slack for a human', critical: true });
}

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  // A sub-workflow can finish green and still have failed to deliver. Lead
  // Escalation now answers with its own verdict; believe it over the exit code.
  if (typeof j.status === 'string' && /fail|unverified|error/i.test(j.status)) {
    return { ...c, ok: false, why: 'sub-workflow reported ' + j.status };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const critical = dropped.filter(r => r.critical);

// -- 01 Sep 2026 - WHY THERE IS NO 'FAILED' RUNG ANY MORE ---------------------
// Every claim above is tiered critical, so any dropped claim wrote FAILED and
// the PARTIAL rung was unreachable. A live row reads "Customer ready to buy this
// week with clear cash budget. | 2 of 3 claimed steps did not land" under status
// FAILED - the lead was persisted and the run completed; two steps did not land.
// That is a partial delivery, and nexus_outcome_class() in Postgres has been
// carrying a correction rule to say so on this workflow's behalf.
//
// FAILED has exactly one owner: nexus_error_handler, the errorWorkflow set on
// this workflow, which writes it from an Error Trigger when an execution STOPS.
// This node only runs on an execution that did NOT stop, so it cannot honestly
// claim the work could not complete.
//
// KNOWN AND NOT FIXED HERE: two of the three claims on the HOT path are
// UNOBSERVABLE from this node, not dropped. 'Intent Switch' output 0 fans out to
// 'Slack Router (HOT)', 'ERP Sync (HOT)' and 'HOT: Already In A Live Chat?', and
// only the third reaches this node - so $('Slack Router (HOT)').item throws and
// is recorded as "did not run on this branch". Proof: this node wrote its
// verdict at 19:09:41.382Z on 29 Aug; 'Lead Escalation - AI Agent', which runs
// only when Slack Router (HOT) calls it, logged at 19:09:49.680Z - eight seconds
// AFTER being reported as not having run. Fixing that needs a graph change (this
// node would have to run once per branch), so the count above still overstates
// what was lost. PARTIAL is the honest ceiling either way.
//
// `critical` is still computed and still reported; it no longer decides status.
const status = dropped.length ? 'PARTIAL'
             : 'SUCCESS';

const suppressed = (origin === 'whatsapp-bdc' && (intent === 'HOT' || intent === 'WARM'))
  ? ' Outreach deliberately skipped: the customer is already in a live WhatsApp thread.'
  : '';

return [{ json: {
  ...( $input.first().json || {} ),
  delivery: {
    status,
    intent,
    origin,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' — ' + r.why),
    note: (dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
        + (critical.length ? ' (' + critical.length + ' of them critical)' : '')
      : 'all ' + results.length + ' claimed steps verified') + suppressed,
  },
} }];

// mr-rules-01 :: Rule-Based Lead Scorer (deterministic, zero-API, LAST tier)
// ---------------------------------------------------------------------------
// Why this file exists: the AI Lead Scoring Agent's Model Ladder tries up to
// 3 OpenRouter :free models (each with a Groq fallback). When OpenRouter's
// DAILY free quota is exhausted AND Groq also fails/is exhausted, the Model
// Ladder code node throws (attempt >= TIERS.length) and, because it has no
// onError handler, the whole execution dies -- the lead is never scored,
// never routed, never persisted. Nothing downstream of scoring ever runs.
//
// This node is the answer: it makes NO network call, needs NO credential and
// NEVER runs out of quota, so a lead is ALWAYS scored even at zero AI budget.
// It is meant to sit as the terminal tier of the ladder (see
// ops/tenant-precedence/patched4/model-ladder.md for exactly where it is
// wired in) and produces the SAME { lead, ai_decision } shape that
// "Parse AI Decision" produces today, so it can feed straight into
// "Intent Switch" + "Persist Lead (deterministic)" unchanged.
//
// score_source is deliberately the literal string 'RULES' (upper-case), NOT
// 'rules'. This matches leads.score_source's live check constraint
// (leads_score_source_is_a_known_label, migration
// 20260914065739_nx920_a_score_now_says_who_decided_it.sql:
// RULES / AI_SCORE_CONFIRMED / AI_SCORE_FALLBACK / AI_SCORE_UNKNOWN) --
// writing lowercase 'rules' to that column would fail the constraint outright.
// `rules_score` is also emitted (== score) because that is the column NX920
// added for it. See ops/ADR-003-who-decides-the-score.md: per that accepted
// (but, as of this file, not yet n8n-implemented) decision, RULES is meant to
// be the AUTHORITATIVE score for every lead today (zero paying dealers, no
// model on the ladder supports structured output) -- this file only wires it
// in as the ladder's last tier per this task's brief, but it is written so
// that promoting it to score-every-lead later is a one-line change in
// whatever calls it, not a rewrite.
//
// Every point added or subtracted is pushed onto `reasons` so the output is
// auditable by a human (or by Slack: Unclassified Lead) -- this is the whole
// point of a rules engine standing in for an LLM: you can see exactly why.
//
// Inputs used (all already on the `lead` object built by
// "Validate & Enrich Input" -- see master-router.Validate-and-Enrich-Input.js):
//   lead.budget_aed        number|null   -- stated budget in AED
//   lead.vehicle_interest  string|null   -- vehicle named AND/OR raw free-text
//                                           message (Validate & Enrich falls
//                                           back to the raw message when no
//                                           explicit vehicle field is sent)
//   lead.message           string|null   -- optional explicit message text,
//                                           scanned in addition to
//                                           vehicle_interest when present
//   lead.source             string|null  -- lead origin channel
//   lead.phone              string|null
//   lead.email               string|null
//   lead.received_at        ISO string   -- used for the time-of-day signal
//
// Output: { intent: 'HOT'|'WARM'|'COLD', score: 0-100, reason: string,
//           budget_aed: number|null, parse_failed: false,
//           score_source: 'RULES', rules_score: number, score_reasons: string[] }
// ---------------------------------------------------------------------------

// Fixed offset: Asia/Dubai is UTC+4 year-round (no DST). Avoids depending on
// ICU/timezone data being present in whatever sandbox this runs in.
const DUBAI_UTC_OFFSET_HOURS = 4;

// ---- keyword dictionaries (lowercased; matched as substrings) -------------
// English
const LUXURY_KEYWORDS = [
  'range rover', 'land rover', 'bentley', 'rolls royce', 'rolls-royce',
  'ferrari', 'lamborghini', 'porsche', 'maserati', 'aston martin',
  'g63', 'g-wagon', 'g wagon', 'g wagen', 'amg', 's-class', 's class',
  '7 series', 'x7', 'gt3', 'mclaren', 'bentayga', 'cullinan', 'mercedes',
];
const URGENCY_KEYWORDS_EN = [
  'today', 'right now', 'asap', 'urgent', 'urgently', 'ready to buy',
  'cash ready', 'this week', 'immediately', 'right away', 'buy now',
  'need it now', 'visit today', 'test drive today', 'ready to purchase',
];
// Arabic (Gulf-dialect friendly) urgency / buying-intent terms
const URGENCY_KEYWORDS_AR = [
  'عاجل', 'اليوم', 'الآن', 'بسرعة', 'جاهز', 'أريد شراء', 'اشتري الان',
];
// Hinglish / Roman Urdu-Hindi urgency / buying-intent terms
const URGENCY_KEYWORDS_HINGLISH = [
  'jaldi', 'abhi', 'turant', 'chahiye', 'kharidna hai', 'abhi chahiye',
];
const BROWSING_KEYWORDS = [
  'just checking', 'just browsing', 'just looking', 'window shopping',
  'no rush', 'not in a hurry', 'someday', 'not sure yet', 'just curious',
];
const SPAM_KEYWORDS = [
  'click here', 'www.', 'http://', 'https://', 'free followers',
  'crypto', 'bitcoin', 'casino', 'loan approved', 'seo services',
  'backlink', 'guaranteed income', 'work from home', 'viagra',
  'subscribe now', '100% free', 'earn money fast', 'act now buy',
];
const REPEAT_KEYWORDS = [
  'second time', 'third time', 'again', 'as i mentioned', 'as mentioned before',
  'previously asked', 'following up', 'follow up on my', 'already contacted',
  'asked before', 'still waiting for a reply', 'still waiting', 'once more',
];
const HIGH_INTENT_SOURCES = /test.?drive|financing|finance.?application|showroom|whatsapp|website.?form/i;
const LOW_INTENT_SOURCES = /cold.?list|scrape|bulk.?import|purchased.?list/i;

function toText(lead) {
  return [lead && lead.vehicle_interest, lead && lead.message, lead && lead.name]
    .filter((v) => typeof v === 'string' && v.trim().length)
    .join(' \n ')
    .toLowerCase();
}

function matchAny(text, keywords) {
  return keywords.filter((k) => text.includes(k.toLowerCase()));
}

function dubaiHour(isoOrDate) {
  const d = isoOrDate instanceof Date ? isoOrDate : new Date(isoOrDate || Date.now());
  if (Number.isNaN(d.getTime())) return new Date().getUTCHours();
  const utcHour = d.getUTCHours();
  return (utcHour + DUBAI_UTC_OFFSET_HOURS) % 24;
}

/**
 * Pure, deterministic, zero-API lead scorer.
 * @param {object} lead - lead object as built by Validate & Enrich Input.
 * @param {object} [opts]
 * @param {Date|string} [opts.now] - override "current time" for time-of-day
 *   scoring/testing. Defaults to lead.received_at, then real now.
 * @returns {{intent:string, score:number, reason:string, budget_aed:(number|null),
 *            parse_failed:boolean, score_source:string, score_reasons:string[]}}
 */
function scoreLead(lead, opts) {
  lead = lead || {};
  opts = opts || {};
  const reasons = [];
  let score = 0;
  let forcedIntent = null; // set to override the score->tier mapping entirely

  const text = toText(lead);

  // ---- 1. budget_aed (weight up to 35) -------------------------------
  const rawBudget = Number(lead.budget_aed);
  const budget_aed = Number.isFinite(rawBudget) && rawBudget > 0 ? Math.round(rawBudget) : null;
  if (budget_aed === null) {
    reasons.push('no budget stated (+0)');
  } else if (budget_aed >= 300000) {
    score += 35;
    reasons.push(`budget_aed ${budget_aed} >= 300,000 AED: high-value buyer (+35)`);
  } else if (budget_aed >= 100000) {
    score += 22;
    reasons.push(`budget_aed ${budget_aed} in the 100k-300k AED band: solid buyer (+22)`);
  } else {
    score += 8;
    reasons.push(`budget_aed ${budget_aed} is a modest stated budget, still a real number (+8)`);
  }

  // ---- 2. vehicle / message keyword signals --------------------------
  const luxuryHits = matchAny(text, LUXURY_KEYWORDS);
  const specificVehicle = !luxuryHits.length && lead.vehicle_interest &&
    String(lead.vehicle_interest).trim().length > 3;
  if (luxuryHits.length) {
    score += 15;
    reasons.push(`luxury/high-end vehicle keyword(s) matched: ${luxuryHits.join(', ')} (+15)`);
  } else if (specificVehicle) {
    score += 8;
    reasons.push(`a specific vehicle was named ("${lead.vehicle_interest}"), genuine interest signal (+8)`);
  } else {
    reasons.push('no specific vehicle or luxury signal in the text (+0)');
  }

  // ---- 3. urgency keywords, English + Arabic + Hinglish --------------
  const urgencyHitsEn = matchAny(text, URGENCY_KEYWORDS_EN);
  const urgencyHitsAr = matchAny(text, URGENCY_KEYWORDS_AR);
  const urgencyHitsHi = matchAny(text, URGENCY_KEYWORDS_HINGLISH);
  const urgencyHits = [...urgencyHitsEn, ...urgencyHitsAr, ...urgencyHitsHi];
  if (urgencyHits.length) {
    score += 20;
    reasons.push(`urgency/buy-now language matched (EN/AR/Hinglish aware): ${urgencyHits.join(', ')} (+20)`);
  } else {
    reasons.push('no urgency language detected (+0)');
  }

  // ---- 4. browsing / low-intent language ------------------------------
  const browsingHits = matchAny(text, BROWSING_KEYWORDS);
  if (browsingHits.length) {
    score -= 10;
    reasons.push(`browsing/no-rush language matched: ${browsingHits.join(', ')} (-10)`);
  }

  // ---- 5. repeat / follow-up enquiry -----------------------------------
  const repeatHits = matchAny(text, REPEAT_KEYWORDS);
  if (repeatHits.length) {
    score += 10;
    reasons.push(`repeat/follow-up language matched: ${repeatHits.join(', ')} (+10) -- this person has ` +
      'already contacted us before; rules mode cannot check purchase history (no DB call), so this is a ' +
      'text-only proxy for "engaged, possibly getting impatient" and should be prioritised for a fast human reply');
  }

  // ---- 6. contact completeness (weight up to 8) ------------------------
  const hasPhone = !!(lead.phone && String(lead.phone).trim());
  const hasEmail = !!(lead.email && String(lead.email).trim());
  if (hasPhone) { score += 5; reasons.push('phone on file, directly callable/WhatsApp-able (+5)'); }
  if (hasEmail) { score += 3; reasons.push('email on file (+3)'); }
  if (!hasPhone && !hasEmail) {
    reasons.push('NO phone and NO email on file -- this lead cannot be reached through any channel we have; ' +
      'capping the score and forcing COLD regardless of every other signal, because a highly scored but ' +
      'unreachable lead is worse than a low one (it looks actionable but is not)');
    forcedIntent = 'COLD';
  }

  // ---- 7. source signal (weight up to 5) --------------------------------
  const source = String(lead.source || '');
  if (HIGH_INTENT_SOURCES.test(source)) {
    score += 5;
    reasons.push(`source "${source}" is a high-intent channel (test drive / financing / showroom / whatsapp) (+5)`);
  } else if (LOW_INTENT_SOURCES.test(source)) {
    score -= 10;
    reasons.push(`source "${source}" looks like a bulk/cold/purchased list (-10)`);
  }

  // ---- 8. spam detection (dominant, overrides everything above) ---------
  const spamHits = matchAny(text, SPAM_KEYWORDS);
  if (spamHits.length) {
    reasons.push(`spam-pattern keyword(s) matched: ${spamHits.join(', ')} -- overriding score to near-zero ` +
      'and forcing COLD regardless of any other signal above');
    score = Math.max(0, 10 - spamHits.length * 3);
    forcedIntent = 'COLD';
  }

  // ---- 9. time-of-day (weight +/-5, soft signal only) --------------------
  const hour = dubaiHour(opts.now || lead.received_at);
  const isBusinessHours = hour >= 8 && hour < 20;
  if (isBusinessHours) {
    score += 5;
    reasons.push(`received at ${hour}:00 Asia/Dubai, inside business hours (+5)`);
  } else {
    score -= 5;
    reasons.push(`received at ${hour}:00 Asia/Dubai, outside business hours -- follow-up will likely wait for ` +
      'the next shift, small penalty (-5)');
  }

  // ---- clamp + classify ---------------------------------------------------
  score = Math.max(0, Math.min(100, Math.round(score)));

  let intent;
  if (forcedIntent) {
    intent = forcedIntent;
    // A forced-COLD lead should never carry a score that reads as hot to a
    // human skimming a table, even if the raw signals were strong.
    score = Math.min(score, 15);
  } else if (score >= 70) {
    intent = 'HOT';
  } else if (score >= 40) {
    intent = 'WARM';
  } else {
    intent = 'COLD';
  }

  const topReason = reasons[0] || 'deterministic rule-based score';
  const reason = `Rule-based score ${score}/100 -> ${intent}. No AI quota was available for this lead; ` +
    `every signal is listed in score_reasons. Top factor: ${topReason}`;

  return {
    intent,
    score,
    reason,
    budget_aed,
    parse_failed: false,
    score_source: 'RULES',   // matches leads.score_source's live check constraint (NX920)
    rules_score: score,      // matches leads.rules_score (NX920)
    score_reasons: reasons,
  };
}

// ---- CommonJS export for the standalone test harness ---------------------
// `typeof module` is a safe check even where `module` is never declared (an
// n8n Code node sandbox): `typeof` never throws on an undeclared identifier.
// This line never runs inside n8n in a way that affects the node's output --
// n8n's sandbox has no CommonJS `module`, so the guard is simply false there.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { scoreLead };
}

// ---- n8n Code node glue ----------------------------------------------------
// Only executes inside n8n, where the `$input` global exists. Kept last and
// guarded so this same file can be `require()`d by the test harness (where
// `$input` is undefined) without touching n8n's execution API.
if (typeof $input !== 'undefined') {
  const prev = $input.first().json;
  // NX1002/model-ladder patch bug fix (20 Sep 2026, found live on exec
  // 16124/16127): when Model Ladder's retry ladder is exhausted, its
  // onError=continueErrorOutput error-output item is JUST { error: <msg> }
  // -- n8n does NOT carry the node's own input (or .lead) through on a Code
  // node's THROWN error, contrary to this patch's original spec assumption
  // (which guessed this from reading the code, not from a live throw). Read
  // the real lead from the named node instead, same fix as 'Model Ladder'.
  let lead;
  try {
    lead = $('Validate & Enrich Input').first().json.lead;
  } catch (e) {
    lead = prev.lead || prev;
  }
  const ai_decision = scoreLead(lead);
  return [{ json: { lead, ai_decision } }];
}

// Accept a raw webhook POST (data under .body) or a direct/sub-workflow call.
const raw = $input.first().json;
const src = raw.body || raw.lead || raw;

const clean = (v) => (v === undefined || v === null || v === false || v === '') ? null : String(v).trim();

const email = clean(src.email);
const phone = clean(src.phone) || clean(src.whatsapp);

if (!email && !phone) {
  throw new Error('Rejected: inbound lead has neither an email nor a phone number. Keys received: ' + Object.keys(src).join(', '));
}

// ---- TENANT (18 Sep 2026) -------------------------------------------------
// REPLACES the 2 Sep resolver, which read `src.tenant_id` FIRST and only fell
// back to the JWT. That order let an authenticated user of dealership A post
// `tenant_id: <B>` and have this workflow create the leads row under B --
// n8n writes as service_role, which is BYPASSRLS, so nothing downstream would
// have stopped it. The caller's tenant_id is now never a source. It is only
// ever a claim, and a claim that disagrees with the membership row is refused.
//
// Two doors, two rules:
//   * public webhook  -- `Webhook Catch-All` -> `Verify JWT` ->
//     `Tenant For JWT User` -> `Auth Gate` -> here. The ONLY trusted answer is
//     the tenant_members row for the Supabase user behind the verified JWT.
//     No row, or more than one row, means refuse; there is no fallback on this
//     door, because a fallback is exactly how an unverifiable caller acquires
//     a dealership.
//   * internal hop    -- `Called Internally` -> here. The caller is a sibling
//     workflow that already resolved the dealership; `Auth Gate` never ran, so
//     that is how this node tells the doors apart.
//
// Refusals carry the '[NEXUS-UNATTRIBUTED]' prefix at position 0, the contract
// with the NEXUS Error Handler (iYJkh1kztWxZXDbT): the failed execution is
// filed under the quarantine tenant instead of being appended to some real
// dealership's audit trail.
const NEXUS_BUILTIN = { 'default': 'fff6a2b5-cfd5-4460-8383-875bc5826de0' };  // Tenant A
const NEXUS_UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let nexusMap = {};
try { nexusMap = JSON.parse(String($env.NEXUS_TENANT_MAP || '')) || {}; } catch (e) { nexusMap = {}; }
if (!nexusMap || typeof nexusMap !== 'object' || !Object.keys(nexusMap).length) nexusMap = NEXUS_BUILTIN;
const nexusKeys = Object.keys(nexusMap);

// What the caller ASSERTED. Never authoritative; only ever cross-checked.
const claimed = String(src.tenant_id || raw.tenant_id || '');

// Which door? `$()` throws for a node that did not run in this execution.
let viaWebhook = true;
try { $('Auth Gate').all(); } catch (e) { viaWebhook = false; }

let tenant = null;
let tenantSource = 'unresolved';

if (viaWebhook) {
  const ids = Array.from(new Set(
    $('Tenant For JWT User').all()
      .map((i) => (i && i.json ? i.json.tenant_id : null))
      .filter(Boolean)
      .map(String)
  ));
  if (ids.length > 1) {
    throw new Error('[NEXUS-UNATTRIBUTED] Lead rejected: the authenticated user is a member of ' + ids.length + ' dealerships. This endpoint will not choose one on their behalf.');
  }
  if (ids.length === 0 || !NEXUS_UUID.test(ids[0])) {
    throw new Error('[NEXUS-UNATTRIBUTED] Lead rejected: the authenticated user has no tenant_members row. A dealership is never taken from the request body.');
  }
  if (claimed && claimed.toLowerCase() !== ids[0].toLowerCase()) {
    throw new Error('[NEXUS-UNATTRIBUTED] Lead rejected: caller asserted tenant_id ' + claimed + ' but is a member of ' + ids[0] + '. tenant_id is not a caller-selectable field.');
  }
  tenant = ids[0];
  tenantSource = 'jwt_tenant_member';
} else {
  if (NEXUS_UUID.test(claimed)) {
    tenant = claimed;
    tenantSource = 'internal_caller';
  } else if (nexusKeys.length === 1 && NEXUS_UUID.test(String(nexusMap[nexusKeys[0]] || ''))) {
    tenant = String(nexusMap[nexusKeys[0]]);
    tenantSource = 'sole_configured_tenant';
  } else {
    throw new Error('[NEXUS-UNATTRIBUTED] Lead rejected: the internal caller supplied no resolvable tenant_id and ' + nexusKeys.length + ' dealerships are configured. Refusing rather than filing this lead under a guess.');
  }
}

return [{
  json: {
    lead: {
      name: clean(src.name) || clean(src.full_name) || 'Unknown',
      email: email,
      phone: phone,
      vehicle_interest: clean(src.vehicle_interest) || clean(src.vehicleInterest) || clean(src.message) || null,
      budget_aed: src.budget_aed ? Number(src.budget_aed) : null,
      source: clean(src.source) || 'webhook',
      // Travels with the lead so the sub-workflows this router fans out to --
      // the BDC agent, the drip, the ERP sync -- write under the right
      // dealership too.
      tenant_id: tenant,
      tenant_source: tenantSource,
      // Who handed us this lead. 'whatsapp-bdc' means the person is ALREADY in
      // a live WhatsApp thread that the BDC agent has just answered, so the
      // outreach branches below must not fire a canned welcome at them on top
      // of the reply they are reading right now. Everything else -- scoring,
      // the Slack alert, the ERP write, the drip -- still applies.
      origin: clean(src.origin) || 'external',
      received_at: new Date().toISOString()
    }
  }
}];

// SCORING AUTHORITY — read this before changing a number.
//
// 14 Sep 2026 (ADR-003). Zero paying dealers, so the model ladder is entirely
// free-tier and none of those models support structured output. A free model
// that collapses into babble produced ai_score 0 on 13 Sep, and an empty `{}`
// response produced a confident-looking WARM/50. Neither was a verdict.
//
// So: DETERMINISTIC RULES DECIDE. The model still runs, its answer is still
// recorded, and it is labelled as a non-authoritative signal. When two paying
// dealers justify a paid model with real structured output, flip the one
// constant below to 'AI' and the labels flip with it. No schema change.
const AUTHORITY = 'RULES';   // 'RULES' today | 'AI' once a paid structured model is in

const lead = $('Validate & Enrich Input').first().json.lead;
const rawOut = $input.first().json;

// Rules-engine short-circuit: when every AI tier is exhausted, the
// "Rule-Based Lead Scorer" node hands us an already-finished decision
// instead of raw agent text. Detect it by score_source and pass it straight
// through -- do NOT try to regex/JSON-parse it as if it were LLM output.
if (rawOut.ai_decision && rawOut.ai_decision.score_source === 'RULES') {
  return [{ json: { lead: rawOut.lead || lead, ai_decision: rawOut.ai_decision } }];
}

const text = String(rawOut.output ?? rawOut.text ?? '').trim();

// ---------------------------------------------------------------- the model
function extractJson(s) {
  if (!s) return null;
  try { return JSON.parse(s); } catch (e) {}
  const fenced = s.replace(/```(?:json)?/gi, '').trim();
  try { return JSON.parse(fenced); } catch (e) {}
  const first = fenced.indexOf('{');
  const last = fenced.lastIndexOf('}');
  if (first !== -1 && last > first) {
    try { return JSON.parse(fenced.slice(first, last + 1)); } catch (e) {}
  }
  return null;
}

const parsed = extractJson(text);

// A parse that "succeeds" on `{}` is not a verdict. Both fields must actually
// be present and valid, or this is a fallback. That closes the hole where an
// empty model response was indistinguishable from a genuine WARM/50.
const aiIntentRaw = parsed && typeof parsed === 'object'
  ? String(parsed.intent || '').toUpperCase() : '';
const aiScoreNum = parsed && typeof parsed === 'object' ? Number(parsed.score) : NaN;
const aiStructured =
  ['HOT', 'WARM', 'COLD'].includes(aiIntentRaw) && Number.isFinite(aiScoreNum);

const ai = {
  intent: aiStructured ? aiIntentRaw : null,
  score:  aiStructured ? Math.max(0, Math.min(100, Math.round(aiScoreNum))) : null,
  reason: (parsed && parsed.reason) ? String(parsed.reason) : null,
  structured: aiStructured
};

// Budget: only ever trusted from structured JSON. The prose fallback cannot
// tell a budget from a price, a year or a phone number, and a wrong budget is
// worse than none.
const rawBudget = aiStructured ? Number(parsed.budget_aed) : NaN;
const aiBudget = Number.isFinite(rawBudget) && rawBudget > 0 ? Math.round(rawBudget) : null;

// ---------------------------------------------------------------- the rules
// Explainable, deterministic, and every point is attributable to a named
// signal. Nothing here can hallucinate and nothing here can time out.
const msg = String(lead.vehicle_interest || '').toLowerCase();
const budget = Number(lead.budget_aed) > 0 ? Number(lead.budget_aed) : (aiBudget || 0);

const BUY   = /\b(price|pricing|quote|cost|how much|buy|buying|purchase|test drive|testdrive|book|booking|reserve|available|availability|finance|financing|emi|installment|instalment|down payment|cash|trade[- ]?in|exchange)\b/;
const URGENT= /\b(today|tonight|now|asap|urgent|urgently|immediately|tomorrow|this week|right away)\b/;
const GREET = /^(hi|hello|hey|salam|assalam|as-salamu|good (morning|afternoon|evening)|thanks|thank you|ok|okay)\W*$/;

let score = 20;
const why = [];
const add = (n, label) => { score += n; why.push((n >= 0 ? '+' : '') + n + ' ' + label); };

if (lead.phone) add(25, 'reachable by phone');
if (lead.email) add(10, 'email present');

if (!msg)                 add(-15, 'no enquiry text');
else if (GREET.test(msg)) add(-10, 'greeting only, no enquiry');
else if (msg.length >= 3) add(20, 'named an enquiry');

if (BUY.test(msg))    add(25, 'buying-intent phrase');
if (URGENT.test(msg)) add(15, 'urgency phrase');

if (budget >= 100000)   add(15, 'budget >= AED 100k');
else if (budget > 0)    add(10, 'budget stated');

if (String(lead.origin || '') === 'whatsapp-bdc') add(10, 'already in a live WhatsApp thread');

score = Math.max(0, Math.min(100, score));

// No enquiry text and no budget is not a cold lead, it is an unreadable one.
// Send it to a human rather than inventing a temperature for it.
const unreadable = !msg && budget <= 0;
const rules = {
  intent: unreadable ? 'UNKNOWN' : (score >= 70 ? 'HOT' : (score >= 40 ? 'WARM' : 'COLD')),
  score: score,
  reason: unreadable
    ? 'No enquiry text and no budget — rules cannot classify this lead. Needs a human.'
    : ('Rules: ' + why.join(', ') + ' = ' + score + '.')
};

// ------------------------------------------------------------ who decides
const useAi = AUTHORITY === 'AI' && ai.structured;
const decided = useAi ? ai : rules;

// One label, three values, never mixed in a metric.
//   RULES              — the deterministic scorer decided (today's default)
//   AI_SCORE_CONFIRMED — the model returned valid structured JSON and decided
//   AI_SCORE_FALLBACK  — the model did not return a usable verdict
const score_source = useAi
  ? 'AI_SCORE_CONFIRMED'
  : (AUTHORITY === 'AI' ? 'AI_SCORE_FALLBACK' : 'RULES');

const ai_decision = {
  intent: decided.intent,
  score: decided.score,
  reason: [decided.reason, ai.reason ? ('Model said: ' + ai.reason) : null]
            .filter(Boolean).join(' | ') || null,
  budget_aed: aiBudget,

  // provenance — persisted, not just logged
  score_source: score_source,
  rules_score: rules.score,
  rules_intent: rules.intent,
  ai_score_raw: ai.score,
  ai_intent_raw: ai.intent,
  ai_structured: ai.structured,

  // kept for the Slack card and the audit row. True whenever the model failed
  // to produce a usable verdict, whether or not the rules covered for it.
  parse_failed: !ai.structured,
  ai_raw_excerpt: ai.structured ? null : text.substring(0, 300)
};

return [{ json: { lead, ai_decision } }];

// n8n's Agent node accepts a maximum of 2 language models, so a deeper
// fallback chain is built as a retry ladder. Each tier swaps the OpenRouter slot.
// 16 Aug 2026: every id below was verified live against OpenRouter -- it exists,
// it is :free (no paid model, per the free-tier rule), and it actually returned
// a tool_call in a real request. The previous ladder had a PAID gemini tier plus
// two dead ids (gemma-4-31b-it:free rate-limited 429, ling-3.0-flash:free is
// 404 free-tier-discontinued), which is why all 4 tiers failed on live traffic.
//
// 29 Aug 2026: REMOVED tier 1, 'nvidia/nemotron-3-ultra-550b-a55b:free'. It failed
// on BOTH agents inside the same real run -- exec 6251 (BDC, 46.5s wasted) and
// exec 6253 (Router, 45.8s wasted) -- with 'Cannot read properties of undefined
// (reading \'message\')'. The ladder escalated correctly each time, so this is not
// a ladder bug: the model is dead and every single request was paying ~45s for it
// before getting a real answer. That latency is also a direct contributor to
// concurrency exhaustion at 5 production slots.
//
// 30 Aug 2026: groqModel changed from 'llama-3.3-70b-versatile' to
// 'openai/gpt-oss-120b' on every tier. Groq SHUT DOWN llama-3.3-70b-versatile
// for free and developer tiers on 16 Aug 2026 -- their deprecations page names
// openai/gpt-oss-120b as the replacement, their models page marks the old id
// Enterprise/Contact-Sales, and it has no row at all in the free-tier
// rate-limit table. Groq is only the FALLBACK slot, so it had never fired in
// production and nothing surfaced this: it would have failed for the first
// time on the day OpenRouter was already down. The same fix went into the
// WhatsApp BDC agent earlier today; this workflow was missed, which meant the
// two agents disagreed about which model exists.
// Free-tier ceiling: 30 RPM / 1K RPD / 8K TPM / 200K TPD -- tokens-per-minute
// binds well before requests-per-minute on an agent this prompt-heavy.
const GROQ_FALLBACK = 'openai/gpt-oss-120b';
const TIERS = [
  { orModel: 'nvidia/nemotron-3.5-lightning:free',       groqModel: GROQ_FALLBACK },
  { orModel: 'nvidia/nemotron-3-super-120b-a12b:free',   groqModel: GROQ_FALLBACK },
  { orModel: 'minimax/minimax-m2.7:free',                groqModel: GROQ_FALLBACK }
];

const prev = $input.first().json;
// NX1002 persist-first bug fix (20 Sep 2026, found live on exec 16124):
// 'Persist Lead (deterministic)' now runs BEFORE this node and uses
// 'Prefer: return=minimal', so its HTTP response body -- and therefore
// $input.first().json on THIS node's first invocation -- is {} with no
// .lead at all. prev.lead was silently undefined on every tier, which fed
// 'undefined' lead data into the AI agent and into 'Rule-Based Lead Scorer',
// and then made 'Update Lead Scoring (PATCH)' fail outright (tenant_id=
// eq.undefined is not a valid uuid), leaving every lead stuck at
// scoring_state='PENDING' forever. Read lead from the named node instead --
// same pattern 'Parse AI Decision' already uses for the same reason -- so it
// is available on every iteration of this retry loop, not just derived from
// this node's own previous (lead-less) output.
const lead = $('Validate & Enrich Input').first().json.lead;
const attempt = Number(prev.attempt ?? -1) + 1;

if (attempt >= TIERS.length) {
  throw new Error('All ' + TIERS.length + ' model tiers failed for lead ' +
    ((lead && lead.email) || 'unknown') + '. Tried: ' +
    TIERS.map(t => t.orModel + ' / ' + t.groqModel).join(', '));
}

return [{ json: {
  lead: lead,
  attempt: attempt,
  maxTiers: TIERS.length,
  orModel: TIERS[attempt].orModel,
  groqModel: TIERS[attempt].groqModel
} }];

